import{z as i,x as d,o as E,c as A,q as l,j as o,D as r,d as t,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"业绩费与高水位","description":"","frontmatter":{"title":"业绩费与高水位","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/performance-fee-hwm.md","filePath":"quant/performance-fee-hwm.md","lastUpdated":1791063341000}'),p={name:"quant/performance-fee-hwm.md"};function m(h,a,u,f,c,D){const n=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=l('<h1 id="业绩费与高水位" tabindex="-1">业绩费与高水位 <a class="header-anchor" href="#业绩费与高水位" aria-label="Permalink to &quot;业绩费与高水位&quot;">​</a></h1><div class="epigraph"><p>高水位把管理人的激励费变成对净值路径的看涨：只有越过历史峰值才收费；期权的价值随波动上升，于是费率条款本身会改变愿意承担的风险。</p><footer>—— Goetzmann, Ingersoll and Ross, High-Water Marks and Hedge Fund Management Contracts, Journal of Finance, 2003</footer></div><p><a href="/quant/strategy-lifecycle">上一课</a>收口策略会衰减。业绩单元的缺口是<strong>谁从剩下的 P&amp;L 里先拿走一截</strong>。管理费是对 AUM 的固定抽成；激励费常带高水位（HWM）：净值创出新高才计提。本课写条款如何改变风险激励，以及投资人看到的净收益为何不是毛收益乘以 (1−20%)。主干 <a href="/quant/ir-sharpe">IR/Sharpe</a> 在扣费对象上必须对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Goetzmann–Ingersoll–Ross 把 HWM 写成或有要求权：管理人持有对基金净值的看涨，执行价是当前水位。波动上升提高期权价值，于是在水位以下时，管理人有动机加大风险去「搏回来」，或在无望时放弃努力（关闭基金、另开一只以重置水位）。问题是治理：条款要与锁定期、赎回、自有资本一起看，不能单独谈「2 和 20」。<span class="marginnote">「2 和 20」指每年按规模收 2% 管理费、再对超越高水位的新收益收 20% 激励费。数字实例：1 亿元规模涨了 10%，先抽管理费 200 万，激励费再按约 20% × 1000 万 ≈ 200 万——合计约 4% 的总成本，远不止「没赚就不收费」那么轻。</span>Panageas–Westerfield 等后续工作讨论即使无管理费，HWM 下的风险选择也不是简单的「总是赌博」。</p><p>与策略地图：短波动卖方的左尾会长期停在水位下，激励费为零，管理费仍抽；投资人此时付的是期权费加管理费，不是「没赚钱就不收费」。</p><h3 id="均衡水位与基金关闭" tabindex="-1">均衡水位与基金关闭 <a class="header-anchor" href="#均衡水位与基金关闭" aria-label="Permalink to &quot;均衡水位与基金关闭&quot;">​</a></h3><p>水位远高于净值时，激励费的 delta 接近零，管理人与投资人的利益最分叉。重置水位（新基金、合并、协商打折）是隐性再谈判。回测若用固定 20% 激励、从不重置、从不关闭，会高估投资人净收益的左尾保护。</p><p><span class="marginnote">水晶条款（clawback）、均衡化（equalization）和系列份额是为了不同时点申购者之间的公平，不是为了提高夏普。忽略它们会把费用算错到份额层面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合同：管理费、激励费、HWM、 hurdle、结晶频率、clawback。<span class="marginnote">hurdle（门槛收益率）是另一道闸门：净值增速先要超过某个基准（如国债利率的 5%）才计提激励费。常见误区：以为有 HWM 就等于有 hurdle——前者防止对同一块净值重复收费，后者要求先跑赢无风险利率；两者可以同时设，保护程度并不相同。</span>会计：按日净值路径模拟费用，而不是按年收益×20%。对照：同一毛路径在不同波动下的净路径。风险：水位下的杠杆政策必须事先写进产品备忘，不能事后当择时。</p>',11)),(E(),o(B,null,{default:r(()=>[s(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%9C%9F%E5%88%9D%E5%87%80%E5%80%BC%20100%EF%BC%8CHWM%20%E4%B9%9F%E6%98%AF%20100%22%5D%20--%3E%20A%5B%22%E6%B6%A8%E5%88%B0%20120%EF%BC%9A%E5%AF%B9%E6%96%B0%E5%A2%9E%2020%20%E8%AE%A1%E6%8F%90%2020%25%20%E6%BF%80%E5%8A%B1%E8%B4%B9%22%5D%0A%20%20A%20--%3E%20B%5B%22HWM%20%E6%8A%AC%E5%88%B0%20120%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%B7%8C%E5%88%B0%20105%EF%BC%9A%E4%B8%8D%E8%AE%A1%E6%BF%80%E5%8A%B1%E8%B4%B9%EF%BC%8C%E7%AE%A1%E7%90%86%E8%B4%B9%E7%85%A7%E6%8A%BD%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%B6%A8%E5%9B%9E%20120%EF%BC%9A%E4%BB%8D%E4%B8%8D%E6%94%B6%E8%B4%B9%EF%BC%8C%E5%8F%AA%E6%98%AF%E5%9B%9E%E6%9C%AC%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%86%8D%E6%B6%A8%E5%88%B0%20125%EF%BC%9A%E5%8F%AA%E5%AF%B9%E8%B6%85%E8%BF%87%20120%20%E7%9A%84%205%20%E8%AE%A1%E6%8F%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"激励费是路径依赖的看涨。投资人卖出这笔期权，换来「有技能才付」。技能若不可持续（后课），期权费是纯转移。HWM 保护投资人免于对同一块净值重复付激励，但不保护管理费，也不保护水位下的赌博。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：高水位像跳高比赛的横杆，只有越过历史最高成绩才算新成绩。净值跌了再涨回来，只是回到起点，管理人不能对「修复回来的亏损」再收一次提成——这就是「免于重复付费」的含义，也是它抑制早期赌博动机的原因。")],-1)),(E(),o(B,null,{default:r(()=>[s(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAV%5B%22%E5%87%80%E5%80%BC%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20HWM%5B%22%E9%AB%98%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20HWM%20--%3E%20Call%5B%22%E6%BF%80%E5%8A%B1%E8%B4%B9%E5%A6%82%E7%9C%8B%E6%B6%A8%22%5D%0A%20%20Vol%5B%22%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20Call%0A%20%20UW%5B%22%E6%B0%B4%E4%BD%8D%E4%BB%A5%E4%B8%8B%22%5D%20--%3E%20Risk%5B%22%E9%A3%8E%E9%99%A9%E6%BF%80%E5%8A%B1%E5%88%86%E5%8F%89%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何设计合同去规避监管或误导披露。税务对激励费的处理因辖区而异。下一课把管理费与激励费一起放进复利。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高水位使激励费成为路径依赖期权，改变风险激励。</li><li>水位以下管理费仍在抽；净收益不是毛收益×0.8。</li><li>关闭与重置水位是隐性再谈判，回测要包含。</li><li>出处：Goetzmann, Ingersoll and Ross, <em>JF</em>, 2003；后续风险选择见 Panageas and Westerfield 等。</li></ul>',4))])}const _=i(p,[["render",m]]);export{F as __pageData,_ as default};
